"use strict";
import { getTokenDetailsURL } from "graphql/data/util";
import { approvedERC20, approvedERC721, TokenStandard } from "pages/Landing/assets/approvedTokens";
import { Ticker } from "pages/Landing/components/TokenCloud/Ticker";
import { useCallback } from "react";
import { useNavigate } from "react-router-dom";
import { IconCloud } from "uniswap/src/components/IconCloud/IconCloud";
import { mixArrays } from "uniswap/src/components/IconCloud/utils";
const tokenList = mixArrays(approvedERC20, approvedERC721, 0.33);
export function TokenCloud() {
  const renderOuterElement = useCallback((item) => {
    return <Ticker itemPoint={item} />;
  }, []);
  const getElementRounded = useCallback((item) => {
    return item.itemData.standard === TokenStandard.ERC20;
  }, []);
  const navigate = useNavigate();
  const onPress = useCallback(
    (item) => {
      const { address, chain, standard } = item.itemData;
      navigate(
        standard === TokenStandard.ERC20 ? getTokenDetailsURL({
          address,
          chain
        }) : `/nfts/collection/${address}`
      );
    },
    [navigate]
  );
  return <IconCloud
    data={tokenList}
    renderOuterElement={renderOuterElement}
    getElementRounded={getElementRounded}
    onPress={onPress}
  />;
}
