"use strict";
import { MenuLink } from "components/NavBar/CompanyMenu/MenuDropdown";
import { NavDropdown } from "components/NavBar/NavDropdown";
import { getSettingsViewIndex } from "components/NavBar/PreferencesMenu";
import { PreferencesView } from "components/NavBar/PreferencesMenu/shared";
import { useTabsContentMobile } from "components/NavBar/Tabs/TabsContent";
import { useTheme } from "lib/styled-components";
import { useCallback, useEffect, useRef, useState } from "react";
import { ChevronDown } from "react-feather";
import { Accordion, AnimateTransition, Flex, Square, Text } from "ui/src";
import { TestID } from "uniswap/src/test/fixtures/testIDs";
function MenuSection({
  title = "",
  children,
  collapsible = true
}) {
  const theme = useTheme();
  return <Accordion.Item value={title} disabled={!collapsible}>
      <Flex gap="10px">
        <Accordion.Trigger flexDirection="row" p="0" gap="4px">
          {({ open }) => <>
              <Text variant="body1" color="$neutral1">
                {title}
              </Text>
              {collapsible && <Square animation="200ms" rotate={open ? "-180deg" : "0deg"}>
                  <ChevronDown size="20px" color={theme.neutral2} />
                </Square>}
            </>}
        </Accordion.Trigger>
        <Accordion.Content p="0" forceMount={!collapsible || void 0}>
          <Flex gap="10px">{children}</Flex>
        </Accordion.Content>
      </Flex>
    </Accordion.Item>;
}
export function MobileMenuDrawer({ isOpen, closeMenu }) {
  const [openSections, setOpenSections] = useState();
  const [settingsView, setSettingsView] = useState(PreferencesView.SETTINGS);
  const dropdownRef = useRef(null);
  const changeView = useCallback(
    (view) => {
      setSettingsView(view);
      if (dropdownRef?.current) {
        dropdownRef.current.scroll({
          top: 0
        });
      }
    },
    [setSettingsView, dropdownRef]
  );
  const onExitPreferencesMenu = useCallback(() => changeView(PreferencesView.SETTINGS), [changeView]);
  const tabsContent = useTabsContentMobile();
  useEffect(() => {
    if (!isOpen) {
      setTimeout(() => setOpenSections([]), 300);
    }
  }, [isOpen]);
  return <NavDropdown dropdownRef={dropdownRef} isOpen={isOpen} dataTestId={TestID.CompanyMenuMobileDrawer}>
      <Flex pt="$spacing12" pb="$spacing32" px="$spacing24">
        <AnimateTransition
    currentIndex={getSettingsViewIndex(settingsView)}
    animationType={settingsView === PreferencesView.SETTINGS ? "forward" : "backward"}
  >
          <Accordion
    overflow="hidden"
    width="100%"
    type="multiple"
    value={openSections}
    onValueChange={setOpenSections}
  >
            <Flex gap="$spacing12" mb={"$spacing60"}>
              {tabsContent.map((tab, index) => <MenuLink
    key={`${tab.title}_${index}}`}
    label={tab.title}
    href={tab.href}
    internal
    closeMenu={closeMenu}
  />)}
            </Flex>
          </Accordion>
        </AnimateTransition>
      </Flex>
    </NavDropdown>;
}
